using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
namespace DeadlockOverlay {
 public static class ReviewAnalysis {
  public static string Compare(MatchSummary summary,Player player){
   var result=new List<string>();Func<Player,long?>[] metrics={p=>p.Damage,p=>p.ObjectDamage,p=>p.Healing,p=>p.Souls};string[] names={L.Choose("hero damage","урон героям"),L.Choose("objective damage","урон строениям"),L.Choose("total healing","общее лечение"),L.Choose("net worth","ценность героя")};
   for(int i=0;i<4;i++){var value=metrics[i](player);var values=summary.Players.Select(metrics[i]).ToArray();if(!value.HasValue||values.Length!=12||values.Any(v=>!v.HasValue))continue;var sorted=values.Select(v=>v.Value).OrderBy(v=>v).ToArray();double median=(sorted[5]+(double)sorted[6])/2;if(value>0&&value==sorted[11])result.Add(L.Choose("Match leader in ","Лидер матча: ")+names[i]+" ("+ScoutProfileData.N(value)+").");else if(median>0&&value<median*.75)result.Add(names[i]+L.Choose(" was below the match median: "," ниже медианы матча: ")+ScoutProfileData.N(value)+" / "+ScoutProfileData.N(median)+".");}
   if(result.Count==0)result.Add(L.Choose("No distinct lead or low contribution established from complete match totals.","По полным итогам матча выраженное лидерство или низкий вклад не установлены."));
   result.Add(L.Choose("Totals depend on hero and role. They do not establish skill or explain positioning and decisions.","Итоги зависят от героя и роли. Они не определяют навык и не объясняют позиционирование и решения."));return string.Join(" ",result);
  }
  public static string Progress(ScoutMatchDetail detail){if(detail==null||!detail.Available||detail.Timeline.Length<2)return L.Choose("Not enough recorded snapshots.","Недостаточно записанных срезов.");var first=detail.Timeline.First();var last=detail.Timeline.Last();var text=new List<string>{detail.Timeline.Length+L.Choose(" measured snapshots. "," измеренных срезов. ")};if(first.Souls.HasValue&&last.Souls.HasValue)text.Add(L.Choose("Net worth changed from ","Ценность героя изменилась с ")+ScoutProfileData.N(first.Souls)+L.Choose(" to "," до ")+ScoutProfileData.N(last.Souls)+".");if(first.Damage.HasValue&&last.Damage.HasValue)text.Add(L.Choose("Hero damage increased by ","Урон героям вырос на ")+ScoutProfileData.N(last.Damage-first.Damage)+".");text.Add(L.Choose("Use the snapshot tooltips to inspect exact times. No unmeasured intervals are reconstructed.","Точное время указано в подсказках срезов. Неизмеренные промежутки не восстанавливаются."));return string.Join(" ",text);}
  public static string Previous(Player player,MatchSummary summary){
   string missing=L.Choose("No suitable cached earlier games on this hero. No comparison is invented and no bulk history download is started.","В кеше нет подходящих более ранних игр на этом герое. Сравнение не выдумывается, массовая загрузка истории не запускается.");
   try{long id=PlayerInsightEngine.AccountId(player.SteamId),match;if(id<=0||!long.TryParse(summary.MatchId,out match))return missing;string path=Path.Combine(SettingsManager.Folder,"scout-cache",id+".json");if(!File.Exists(path)||new FileInfo(path).Length>8*1024*1024)return missing;var json=Json.Serializer();json.MaxJsonLength=8*1024*1024;var profile=json.Deserialize<ScoutProfile>(File.ReadAllText(path));if(profile.Account!=id)return missing;var all=ScoutStatistics.History(profile);var current=all.FirstOrDefault(m=>m.Id==match);if(current==null||current.Start<=0)return missing;var prior=all.Where(m=>m.Id!=match&&m.Start<current.Start&&m.Hero==player.Hero&&m.Mode==current.Mode&&m.Duration>0&&m.Souls.HasValue).Take(20).ToArray();if(prior.Length<5||!player.Souls.HasValue||summary.DurationSeconds<=0)return missing;double baseline=prior.Average(m=>m.Souls.Value*60.0/m.Duration.Value),actual=player.Souls.Value*60.0/summary.DurationSeconds.Value;return L.Choose("Net worth per minute: ","Ценность героя за минуту: ")+ScoutProfileData.N(actual)+L.Choose(" now; "," сейчас; ")+ScoutProfileData.N(baseline)+L.Choose(" in "," в ")+prior.Length+L.Choose(" earlier same-hero, same-mode cached games. Patch and role may differ; this is a personal reference, not a skill rating."," более ранних играх на том же герое в том же режиме. Патч и роль могут отличаться; это личный ориентир, не оценка навыка.");}catch{return missing;}
  }
 }
}
